#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Secure message queue with rate limiting and access control
// Designed for embedded systems with strict memory constraints

#define MAX_QUEUE_SIZE 256
#define MAX_MSG_LEN 1024
#define MAX_USERS 64
#define HMAC_LEN 32

typedef struct {
    uint8_t data[MAX_MSG_LEN];
    uint16_t length;
    uint32_t timestamp;
    uint8_t sender_id;
    uint8_t priority;
} Message;

typedef struct {
    Message messages[MAX_QUEUE_SIZE];
    uint8_t head;
    uint8_t tail;
    uint8_t count;
    uint8_t capacity;
} MessageQueue;

typedef struct {
    uint8_t user_id;
    uint8_t role;  // 0=guest, 1=user, 2=admin
    uint32_t rate_tokens;
    uint32_t last_refill;
    char username[32];
    uint8_t hmac_key[HMAC_LEN];
} UserSession;

typedef struct {
    UserSession sessions[MAX_USERS];
    uint8_t session_count;
    MessageQueue queues[4];  // priority queues 0-3
} ServerState;

static ServerState g_state;

// Simple HMAC verification (simplified for embedded)
static bool verify_hmac(const uint8_t *data, size_t data_len,
                        const uint8_t *key, const uint8_t *provided_hmac) {
    uint8_t computed[HMAC_LEN];
    // Simplified HMAC: XOR-based MAC for embedded systems
    memset(computed, 0, HMAC_LEN);
    for (size_t i = 0; i < data_len; i++) {
        computed[i % HMAC_LEN] ^= data[i] ^ key[i % HMAC_LEN];
    }
    // Constant-time comparison to prevent timing attacks
    uint8_t diff = 0;
    for (int i = 0; i < HMAC_LEN; i++) {
        diff |= computed[i] ^ provided_hmac[i];
    }
    return diff == 0;
}

// Rate limiter using token bucket algorithm
static bool check_rate_limit(UserSession *session, uint32_t current_time) {
    uint32_t elapsed = current_time - session->last_refill;
    if (elapsed > 0) {
        // Refill tokens: 1 token per second, max 10
        uint32_t new_tokens = session->rate_tokens + elapsed;
        session->rate_tokens = (new_tokens > 10) ? 10 : new_tokens;
        session->last_refill = current_time;
    }
    if (session->rate_tokens > 0) {
        session->rate_tokens--;
        return true;
    }
    return false;
}

// Access control check
static bool check_access(UserSession *session, uint8_t required_role) {
    return session->role >= required_role;
}

// Initialize a message queue
static void queue_init(MessageQueue *q, uint8_t capacity) {
    q->head = 0;
    q->tail = 0;
    q->count = 0;
    q->capacity = capacity;
    memset(q->messages, 0, sizeof(q->messages));
}

// Enqueue with bounds checking
static int queue_enqueue(MessageQueue *q, const Message *msg) {
    if (q->count >= q->capacity) {
        return -1;  // Queue full
    }
    memcpy(&q->messages[q->tail], msg, sizeof(Message));
    q->tail = (q->tail + 1) % q->capacity;
    q->count++;
    return 0;
}

// Dequeue with bounds checking  
static int queue_dequeue(MessageQueue *q, Message *msg) {
    if (q->count == 0) {
        return -1;  // Queue empty
    }
    memcpy(msg, &q->messages[q->head], sizeof(Message));
    q->head = (q->head + 1) % q->capacity;
    q->count--;
    return 0;
}

// Batch copy: copies 'n' messages starting from offset into output buffer
// Used for admin bulk-read operations
static int queue_batch_read(MessageQueue *q, uint8_t start_offset,
                            uint8_t num_messages, Message *output,
                            uint8_t output_capacity) {
    // Validate that we won't read beyond what's in the queue
    if (start_offset >= q->count) {
        return -1;  // Invalid offset
    }

    // Calculate how many messages we can actually read
    // Ensure we don't exceed queue contents or output buffer
    uint8_t available = q->count - start_offset;
    uint8_t to_read = (num_messages < available) ? num_messages : available;

    // Safety check: ensure to_read fits in output buffer
    // Both to_read and output_capacity are uint8_t (0-255)
    if (to_read > output_capacity) {
        to_read = output_capacity;
    }

    // Copy messages from circular buffer
    for (uint8_t i = 0; i < to_read; i++) {
        uint8_t idx = (q->head + start_offset + i) % q->capacity;
        memcpy(&output[i], &q->messages[idx], sizeof(Message));
    }

    return to_read;
}

// Process incoming request from network
// Format: [1B cmd][1B user_id][32B hmac][payload...]
int process_request(const uint8_t *request, size_t request_len,
                    uint8_t *response, size_t *response_len,
                    uint32_t current_time) {
    if (request_len < 34) {  // minimum: cmd + user_id + hmac
        return -1;
    }

    uint8_t cmd = request[0];
    uint8_t user_id = request[1];
    const uint8_t *hmac = &request[2];
    const uint8_t *payload = &request[34];
    size_t payload_len = request_len - 34;

    // Find user session
    UserSession *session = NULL;
    for (int i = 0; i < g_state.session_count; i++) {
        if (g_state.sessions[i].user_id == user_id) {
            session = &g_state.sessions[i];
            break;
        }
    }
    if (!session) {
        return -2;  // Unknown user
    }

    // Verify HMAC over cmd + payload
    uint8_t hmac_input[MAX_MSG_LEN + 1];
    if (payload_len + 1 > sizeof(hmac_input)) {
        return -3;
    }
    hmac_input[0] = cmd;
    memcpy(&hmac_input[1], payload, payload_len);
    if (!verify_hmac(hmac_input, payload_len + 1, session->hmac_key, hmac)) {
        return -4;  // Auth failed
    }

    // Rate limit check
    if (!check_rate_limit(session, current_time)) {
        return -5;  // Rate limited
    }

    switch (cmd) {
        case 0x01: {  // SEND_MESSAGE
            if (payload_len < 3) return -6;
            uint8_t priority = payload[0];
            uint16_t msg_len = (uint16_t)payload[1] | ((uint16_t)payload[2] << 8);

            if (priority > 3) return -6;
            if (msg_len > MAX_MSG_LEN || msg_len + 3 > payload_len) return -6;

            Message msg;
            memset(&msg, 0, sizeof(msg));
            memcpy(msg.data, &payload[3], msg_len);
            msg.length = msg_len;
            msg.timestamp = current_time;
            msg.sender_id = user_id;
            msg.priority = priority;

            if (queue_enqueue(&g_state.queues[priority], &msg) != 0) {
                return -7;  // Queue full
            }
            *response_len = 1;
            response[0] = 0x01;  // ACK
            return 0;
        }

        case 0x02: {  // READ_MESSAGE
            if (payload_len < 1) return -6;
            uint8_t priority = payload[0];
            if (priority > 3) return -6;

            Message msg;
            if (queue_dequeue(&g_state.queues[priority], &msg) != 0) {
                *response_len = 1;
                response[0] = 0x00;  // No messages
                return 0;
            }
            response[0] = 0x02;
            memcpy(&response[1], &msg, sizeof(Message));
            *response_len = 1 + sizeof(Message);
            return 0;
        }

        case 0x03: {  // ADMIN_BATCH_READ - requires admin role
            if (!check_access(session, 2)) {
                return -8;  // Access denied
            }
            if (payload_len < 3) return -6;

            uint8_t priority = payload[0];
            uint8_t offset = payload[1];
            uint8_t count = payload[2];

            if (priority > 3) return -6;

            // Allocate output on stack - sized for the request
            // The caller requests 'count' messages; we cap at 32 for stack safety
            uint8_t safe_count = (count > 32) ? 32 : count;
            Message batch[32];
            memset(batch, 0, sizeof(batch));

            int read = queue_batch_read(&g_state.queues[priority],
                                        offset, safe_count, batch, safe_count);
            if (read < 0) {
                return -9;
            }

            response[0] = 0x03;
            response[1] = (uint8_t)read;
            memcpy(&response[2], batch, read * sizeof(Message));
            *response_len = 2 + read * sizeof(Message);
            return 0;
        }

        case 0x04: {  // ADMIN_RESIZE_QUEUE - requires admin role
            if (!check_access(session, 2)) {
                return -8;
            }
            if (payload_len < 2) return -6;

            uint8_t priority = payload[0];
            uint8_t new_capacity = payload[1];

            if (priority > 3) return -6;
            // Capacity must be reasonable
            if (new_capacity == 0 || new_capacity > MAX_QUEUE_SIZE) return -6;

            g_state.queues[priority].capacity = new_capacity;
            response[0] = 0x04;
            *response_len = 1;
            return 0;
        }

        default:
            return -10;
    }
}

void server_init(void) {
    memset(&g_state, 0, sizeof(g_state));
    for (int i = 0; i < 4; i++) {
        queue_init(&g_state.queues[i], MAX_QUEUE_SIZE);
    }
}

int add_user(uint8_t user_id, uint8_t role, const char *username,
             const uint8_t *hmac_key) {
    if (g_state.session_count >= MAX_USERS) return -1;
    UserSession *s = &g_state.sessions[g_state.session_count];
    s->user_id = user_id;
    s->role = role;
    s->rate_tokens = 10;
    s->last_refill = 0;
    strncpy(s->username, username, sizeof(s->username) - 1);
    s->username[sizeof(s->username) - 1] = '\0';
    memcpy(s->hmac_key, hmac_key, HMAC_LEN);
    g_state.session_count++;
    return 0;
}
